import asyncio
from typing import Any, Awaitable, Callable


async def gather_limited(
    factories: list[Callable[[], Awaitable[Any]]],
    limit: int,
    timeout: float | None = None,
) -> list:
    if limit < 1:
        raise ValueError("limit must be >= 1")

    n = len(factories)
    if n == 0:
        return []

    results: list[Any] = [None] * n
    first_error: BaseException | None = None
    first_error_time: float | None = None
    loop = asyncio.get_running_loop()

    tasks: dict[int, asyncio.Task] = {}
    next_idx = 0
    error_raised = False

    async def _run_one(idx: int) -> None:
        nonlocal first_error, first_error_time
        try:
            if timeout is not None:
                result = await asyncio.wait_for(factories[idx](), timeout=timeout)
            else:
                result = await factories[idx]()
            results[idx] = result
        except asyncio.CancelledError:
            raise
        except Exception as e:
            t = loop.time()
            if first_error_time is None or t < first_error_time:
                first_error_time = t
                first_error = e

    async def _main() -> None:
        nonlocal next_idx, error_raised
        while True:
            # Start tasks up to limit
            while next_idx < n and len(tasks) < limit:
                idx = next_idx
                next_idx += 1
                task = asyncio.create_task(_run_one(idx))
                tasks[idx] = task

            if not tasks:
                break

            # Wait for at least one task to complete
            done, _ = await asyncio.wait(
                list(tasks.values()), return_when=asyncio.FIRST_COMPLETED
            )

            # Check for errors in completed tasks
            for task in done:
                try:
                    task.result()
                except asyncio.CancelledError:
                    pass
                except Exception as e:
                    if not error_raised:
                        error_raised = True

            # Remove completed tasks
            for idx, task in list(tasks.items()):
                if task.done():
                    del tasks[idx]

            # If an error occurred, stop starting new tasks and cancel running ones
            if error_raised:
                break

    try:
        await _main()
    except asyncio.CancelledError:
        # gather_limited was cancelled - cancel all running tasks and wait
        for task in tasks.values():
            if not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks.values(), return_exceptions=True)
        raise

    # If an error occurred, cancel any remaining running tasks and wait for cleanup
    if first_error is not None:
        for task in tasks.values():
            if not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks.values(), return_exceptions=True)
        raise first_error

    # Wait for any remaining tasks (shouldn't be any if no error, but just in case)
    if tasks:
        await asyncio.gather(*tasks.values(), return_exceptions=True)

    return results
