import datetime


def _parse_field(field: str, min_val: int, max_val: int, names: dict = None) -> set:
    """Parse a single cron field and return the set of matching values."""
    if names is None:
        names = {}

    values = set()

    # Check if the entire field is just '*'
    stripped = field.strip()
    if stripped == '*':
        return set(range(min_val, max_val + 1))

    items = stripped.split(',')
    for item in items:
        item = item.strip()
        if not item:
            raise ValueError(f"Empty item in field: {field}")

        # Handle step
        step = 1
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax: {item}")
            item_base, step_str = parts
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive: {step}")
        else:
            item_base = item

        # Parse the base part
        if item_base == '*':
            start = min_val
            end = max_val
        elif '-' in item_base:
            range_parts = item_base.split('-')
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range syntax: {item_base}")
            a_str, b_str = range_parts
            a = _parse_value(a_str.strip(), min_val, max_val, names)
            b = _parse_value(b_str.strip(), min_val, max_val, names)
            if a > b:
                raise ValueError(f"Range start greater than end: {a}-{b}")
            start = a
            end = b
        else:
            val = _parse_value(item_base, min_val, max_val, names)
            if '/' in item:
                # A/S means from A to max
                start = val
                end = max_val
            else:
                values.add(val)
                continue

        for v in range(start, end + 1, step):
            values.add(v)

    return values


def _parse_value(s: str, min_val: int, max_val: int, names: dict = None) -> int:
    """Parse a single value (number or name) from a cron field."""
    if names is None:
        names = {}

    s_upper = s.upper()
    if s_upper in names:
        return names[s_upper]

    try:
        val = int(s)
    except ValueError:
        raise ValueError(f"Unknown value or name: {s}")

    if val < min_val or val > max_val:
        raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")

    return val


MONTH_NAMES = {
    'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
    'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
}

DOW_NAMES = {
    'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
}


def _parse_cron(expr: str) -> tuple:
    """Parse a cron expression into sets of valid values for each field."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_str, hour_str, dom_str, month_str, dow_str = fields

    minutes = _parse_field(minute_str, 0, 59)
    hours = _parse_field(hour_str, 0, 23)
    days_of_month = _parse_field(dom_str, 1, 31)
    months = _parse_field(month_str, 1, 12, MONTH_NAMES)

    # For day-of-week, 7 is treated as 0 (Sunday)
    dow_raw = _parse_field(dow_str, 0, 7, DOW_NAMES)
    days_of_week = set()
    for d in dow_raw:
        if d == 7:
            days_of_week.add(0)
        else:
            days_of_week.add(d)

    return minutes, hours, days_of_month, months, days_of_week


def _is_restricted(field_str: str) -> bool:
    """Check if a field is restricted (not exactly '*')."""
    return field_str.strip() != '*'


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """Find the next fire time strictly after `after` for the given cron expression."""
    minutes, hours, days_of_month, months, days_of_week = _parse_cron(expr)

    # Get original field strings to check restriction
    fields = expr.split()
    dom_str = fields[2].strip()
    dow_str = fields[4].strip()
    dom_restricted = _is_restricted(dom_str)
    dow_restricted = _is_restricted(dow_str)

    # Start from the next minute after `after`
    current = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # We'll search up to 5 years ahead
    max_date = after + datetime.timedelta(days=366 * 5)

    while current < max_date:
        # Check month
        if current.month not in months:
            # Advance to the first day of the next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Check day of month and day of week using Vixie cron rules
        # Python's weekday(): Monday=0, Sunday=6. Cron: Sunday=0, Saturday=6.
        # Convert Python weekday to cron dow: (python_weekday + 1) % 7
        python_weekday = current.weekday()  # Mon=0 ... Sun=6
        cron_dow = (python_weekday + 1) % 7  # Sun=0, Mon=1, ..., Sat=6

        dom_match = current.day in days_of_month
        dow_match = cron_dow in days_of_week

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if not day_ok:
            # Advance to the next day
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if current.hour not in hours:
            # Find the next valid hour today
            found_hour = False
            for h in sorted(hours):
                if h > current.hour:
                    current = current.replace(hour=h, minute=0)
                    found_hour = True
                    break
            if not found_hour:
                # No more hours today, go to next day
                current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check minute
        if current.minute not in minutes:
            # Find the next valid minute in this hour
            found_minute = False
            for m in sorted(minutes):
                if m > current.minute:
                    current = current.replace(minute=m)
                    found_minute = True
                    break
            if not found_minute:
                # No more minutes this hour, go to next hour
                if current.hour < 23:
                    current = current.replace(hour=current.hour + 1, minute=0)
                else:
                    current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # All fields match
        return current

    raise ValueError("No matching time found within the next 5 years")
