import copy


def merge(base: dict, *overrides: dict) -> dict:
    """Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists replaced).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends to a list: {"key+": [...]} appends items to
      base's "key" list. If base has no "key", creates new list. If base has
      "key" but it's not a list, raises TypeError. The '+' key never appears
      in the result.
    - Inputs are not mutated; result is a deep copy (no shared mutable containers).
    """
    # Start with a deep copy of the base dict
    result = _deep_copy_dict(base)

    for override in overrides:
        result = _merge_into(result, override)

    return result


def _deep_copy_dict(d: dict) -> dict:
    """Create a deep copy of a dictionary."""
    if not isinstance(d, dict):
        raise TypeError("Expected a dict")
    return {k: copy.deepcopy(v) for k, v in d.items()}


def _merge_into(base: dict, override: dict) -> dict:
    """Merge override into base (both dicts), returning a new dict.

    Does not mutate either input. Returns a new deep-copied result.
    """
    # Start with a deep copy of base
    result = {k: copy.deepcopy(v) for k, v in base.items()}

    for key, value in override.items():
        if key.endswith('+'):
            # Append mode
            actual_key = key[:-1]
            if not isinstance(value, list):
                raise TypeError(f"Value for append key '{key}' must be a list")
            if actual_key in result:
                base_val = result[actual_key]
                if not isinstance(base_val, list):
                    raise TypeError(
                        f"Cannot append to non-list value for key '{actual_key}'"
                    )
                # Append items (deep copy of the override's items)
                result[actual_key] = base_val + copy.deepcopy(value)
            else:
                # No existing key, create new list with deep-copied items
                result[actual_key] = copy.deepcopy(value)
        elif value is None:
            # Delete the key from result if it exists
            if key in result:
                del result[key]
        elif isinstance(value, dict):
            # Recursive merge for dicts
            if key in result and isinstance(result[key], dict):
                result[key] = _merge_into(result[key], value)
            else:
                # Override with a new deep-copied dict
                result[key] = copy.deepcopy(value)
        else:
            # Replace with deep copy of the override value
            result[key] = copy.deepcopy(value)

    return result
