def parse_duration(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError("Empty or invalid input")

    units = ['d', 'h', 'm', 's']
    unit_values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    total_seconds = 0
    i = 0
    n = len(s)
    last_unit_index = -1

    while i < n:
        # Skip a single space if present (but not at the very start)
        if s[i] == ' ':
            i += 1
            continue

        # Find the number
        num_start = i
        while i < n and s[i].isdigit():
            i += 1

        if i == num_start:
            raise ValueError(f"Missing number at position {num_start}")

        num_str = s[num_start:i]
        number = int(num_str)

        # Next should be a unit character
        if i >= n:
            raise ValueError("Missing unit")

        unit_char = s[i].lower()
        if unit_char not in units:
            raise ValueError(f"Unknown unit '{s[i]}'")

        i += 1

        # Check order
        current_unit_index = units.index(unit_char)
        if current_unit_index <= last_unit_index:
            raise ValueError("Units out of order or repeated")
        last_unit_index = current_unit_index

        total_seconds += number * unit_values[unit_char]

        # After the unit, either end of string or a single space before next number
        if i < n:
            if s[i] == ' ':
                i += 1  # skip the space
            elif not s[i].isdigit():
                raise ValueError(f"Invalid character '{s[i]}' after unit")

    return total_seconds


def format_duration(seconds: int) -> str:
    if not isinstance(seconds, int):
        raise ValueError("Input must be an integer")
    if seconds < 0:
        raise ValueError("Negative input")

    if seconds == 0:
        return "0s"

    parts = []

    days = seconds // 86400
    remainder = seconds % 86400

    hours = remainder // 3600
    remainder = remainder % 3600

    minutes = remainder // 60
    seconds_remaining = remainder % 60

    if days > 0:
        parts.append(f"{days}d")
    if hours > 0:
        parts.append(f"{hours}h")
    if minutes > 0:
        parts.append(f"{minutes}m")
    if seconds_remaining > 0:
        parts.append(f"{seconds_remaining}s")

    return "".join(parts)
