        return self.pos >= len(self.tokens)

    def parse(self):
        if self.at_end():
            raise SyntaxError("Empty input")
        result = self.parse_conditional()
        if not self.at_end():
            tok = self.peek()
            raise SyntaxError(f"Unexpected token {tok.kind}({tok.value!r}) after expression")
        return result

    def parse_conditional(self):
        cond = self.parse_or()
        tok = self.peek()
        if tok is not None and tok.kind == "op" and tok.value == "?":
            self.advance()
            then_branch = self.parse_conditional()
            self.expect("op", ":")
            else_branch = self.parse_conditional()
            if cond != 0:
                return then_branch
            else:
                return else_branch
        return cond

    def parse_or(self):
        left = self.parse_and()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "op" and tok.value == "||":
                self.advance()
                if left != 0:
                    old_skipping = self._skipping
                    self._skipping = True
                    self.parse_and()
                    self._skipping = old_skipping
                    left = 1
                else:
                    right = self.parse_and()
                    left = 1 if right != 0 else 0
            else:
                break
        return left

    def parse_and(self):
        left = self.parse_comparison()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "op" and tok.value == "&&":
                self.advance()
                if left == 0:
                    old_skipping = self._skipping
                    self._skipping = True
                    self.parse_comparison()
                    self._skipping = old_skipping
                    left = 0
                else:
                    right = self.parse_comparison()
                    left = 1 if right != 0 else 0
            else:
                break
        return left

    def parse_comparison(self):
        if self._skipping:
            self.parse_additive()
            tok = self.peek()
            if tok is not None and tok.kind == "op" and tok.value in ("==", "!=", "<", "<=", ">", ">="):
                self.advance()
                self.parse_additive()
                tok2 = self.peek()
                if tok2 is not None and tok2.kind == "op" and tok2.value in ("==", "!=", "<", "<=", ">", ">="):
                    raise SyntaxError(f"Non-associative comparison: cannot chain {tok2.value}")
            return 0

        left = self.parse_additive()
        tok = self.peek()
        if tok is not None and tok.kind == "op" and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            op = self.advance().value
            right = self.parse_additive()
            if op == "==":
                result = 1 if left == right else 0
            elif op == "!=":
                result = 1 if left != right else 0
            elif op == "<":
                result = 1 if left < right else 0
            elif op == "<=":
                result = 1 if left <= right else 0
            elif op == ">":
                result = 1 if left > right else 0
            elif op == ">=":
                result = 1 if left >= right else 0
            tok2 = self.peek()
            if tok2 is not None and tok2.kind == "op" and tok2.value in ("==", "!=", "<", "<=", ">", ">="):
                raise SyntaxError(f"Non-associative comparison: cannot chain {tok2.value}")
            return result
        return left

    def parse_additive(self):
        if self._skipping:
            self.parse_multiplicative()
            while True:
                tok = self.peek()
                if tok is not None and tok.kind == "op" and tok.value in ("+", "-"):
                    self.advance()
                    self.parse_multiplicative()
                else:
                    break
            return 0

        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "op" and tok.value in ("+", "-"):
                op = self.advance().value
                right = self.parse_multiplicative()
                if op == "+":
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_multiplicative(self):
        if self._skipping:
            self.parse_unary()
            while True:
                tok = self.peek()
                if tok is not None and tok.kind == "op" and tok.value in ("*", "/", "%"):
                    self.advance()
                    self.parse_unary()
                else:
                    break
            return 0

        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "op" and tok.value in ("*", "/", "%"):
                op = self.advance().value
                right = self.parse_unary()
                if op == "*":
                    left = left * right
                elif op == "/":
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    if isinstance(left, int) and isinstance(right, int):
                        if left % right == 0:
                            left = left // right
                        else:
                            left = left / right
                    else:
                        left = left / right
                elif op == "%":
                    if right == 0:
                        raise ZeroDivisionError("modulo by zero")
                    left = left % right
            else:
                break
        return left

    def parse_unary(self):
        tok = self.peek()
        if tok is not None and tok.kind == "op" and tok.value in ("-", "+", "!"):
            op = self.advance().value
            operand = self.parse_power()
            if self._skipping:
                return 0
            if op == "-":
                return -operand
            elif op == "+":
                return +operand
            elif op == "!":
                return 1 if operand == 0 else 0
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        tok = self.peek()
        if tok is not None and tok.kind == "op" and tok.value == "^":
            self.advance()
            exponent = self.parse_unary()
            if self._skipping:
                return 0
            return base ** exponent
        return base

    def parse_atom(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxError("Unexpected end of input, expected atom")

        if tok.kind == "number":
            self.advance()
            if self._skipping:
                return 0
            return tok.value

        if tok.kind == "ident":
            self.advance()
            name = tok.value
            next_tok = self.peek()
            if next_tok is not None and next_tok.kind == "lparen":
                self.advance()
                args = []
                if self.peek() is not None and self.peek().kind == "rparen":
                    self.advance()
                else:
                    while True:
                        args.append(self.parse_conditional())
                        next_tok = self.peek()
                        if next_tok is None:
                            raise SyntaxError("Expected ',' or ')' in function call")
                        if next_tok.kind == "comma":
                            self.advance()
                            continue
                        elif next_tok.kind == "rparen":
                            self.advance()
                            break
                        else:
                            raise SyntaxError(f"Expected ',' or ')' but got {next_tok.kind}({next_tok.value!r})")

                if name == "min":
                    if len(args) < 1:
                        raise SyntaxError("min requires at least 1 argument")
                    if self._skipping:
                        return 0
                    return min(args)
                elif name == "max":
                    if len(args) < 1:
                        raise SyntaxError("max requires at least 1 argument")
                    if self._skipping:
                        return 0
                    return max(args)
                elif name == "abs":
                    if len(args) != 1:
                        raise SyntaxError("abs requires exactly 1 argument")
                    if self._skipping:
                        return 0
                    return abs(args[0])
                else:
                    raise NameError(f"Unknown function: {name}")
            else:
                if name not in self.env:
                    raise NameError(f"Undefined variable: {name}")
                if self._skipping:
                    return 0
                return self.env[name]

        if tok.kind == "lparen":
            self.advance()
            result = self.parse_conditional()
            self.expect("rparen", ")")
            if self._skipping:
                return 0
            return result

        raise SyntaxError(f"Unexpected token {tok.kind}({tok.value!r}) in atom position")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if not expr or not expr.strip():
        raise SyntaxError("Empty input")
    tokens = _tokenize(expr)
    parser = _Parser(tokens, env)
    return parser.parse()
