import heapq
from collections import defaultdict


def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = set(len(row) for row in grid)
    if len(cols) != 1:
        raise ValueError("Ragged rows")
    cols = cols.pop()

    # Check characters and count S, E, letters
    s_count = 0
    e_count = 0
    letter_counts = defaultdict(int)
    valid_chars = set('S E#.' + '123456789' + 'abcdefghijklmnopqrstuvwxyz'.replace(' ', ''))

    for r in range(rows):
        row = grid[r]
        if len(row) != cols:
            raise ValueError("Ragged rows")
        for c in range(cols):
            ch = row[c]
            if ch == 'S':
                s_count += 1
            elif ch == 'E':
                e_count += 1
            elif ch == '#':
                pass
            elif ch == '.':
                pass
            elif ch.isdigit() and '1' <= ch <= '9':
                pass
            elif ch.islower():
                letter_counts[ch] += 1
            else:
                raise ValueError(f"Unknown character: {ch}")

    if s_count != 1:
        raise ValueError(f"Expected exactly one S, got {s_count}")
    if e_count != 1:
        raise ValueError(f"Expected exactly one E, got {e_count}")

    for letter, count in letter_counts.items():
        if count not in (0, 2):
            raise ValueError(f"Letter '{letter}' appears {count} times")

    # Find S and E positions
    start = None
    end = None
    pad_positions = defaultdict(list)

    for r in range(rows):
        row = grid[r]
        for c in range(cols):
            ch = row[c]
            if ch == 'S':
                start = (r, c)
            elif ch == 'E':
                end = (r, c)
            elif ch.islower():
                pad_positions[ch].append((r, c))

    # Convert each list of 2 positions to a dict mapping position -> other position
    pad_map = {}
    for letter, positions in pad_positions.items():
        if len(positions) == 2:
            pos1, pos2 = positions[0], positions[1]
            pad_map[pos1] = pos2
            pad_map[pos2] = pos1

    # Get cost of a cell
    def get_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif ch.islower():
            return 1
        else:
            return 1  # Should not reach here

    # Dijkstra's algorithm
    # State: (cost, move_string_length, move_string, r, c)
    # We want to minimize cost first, then lexicographically smallest moves string
    # Alphabet order: D < L < R < T < U

    # Directions in the order they should be tried for lexicographic ordering
    # But we need to use a priority queue that orders by (cost, move_string)

    # Since move strings can be long, we'll use a different approach:
    # Use Dijkstra where the key is (cost, moves_string) but that's expensive.
    # Instead, we can do BFS-like with cost as primary and use lexicographic tie-breaking.

    # Actually, let's use a priority queue with (cost, moves_string, r, c)
    # Python tuples compare element-wise, so this works directly.

    INF = float('inf')
    best_cost = {}  # (r, c) -> min cost seen
    best_moves = {}  # (r, c) -> lexicographically smallest moves for that cost

    pq = []
    heapq.heappush(pq, (0, "", start[0], start[1]))

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        # Check if we've reached the end
        if (r, c) == end:
            return (cost, moves)

        # If we've already found a better or equal path to this cell, skip
        if (r, c) in best_cost and cost > best_cost[(r, c)]:
            continue
        if (r, c) in best_cost and cost == best_cost[(r, c)] and moves >= best_moves.get((r, c), ""):
            continue

        # Update best for this cell
        if (r, c) not in best_cost or cost < best_cost[(r, c)] or (cost == best_cost[(r, c)] and moves < best_moves.get((r, c), "")):
            best_cost[(r, c)] = cost
            best_moves[(r, c)] = moves

        # Generate neighbors
        # Moves in lexicographic order: D, L, R, T, U
        # D: (r+1, c), L: (r, c-1), R: (r, c+1), T: teleport, U: (r-1, c)

        moves_to_try = []

        # D
        nr, nc = r + 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            new_cost = cost + get_cost(nr, nc)
            new_moves = moves + "D"
            moves_to_try.append((new_cost, new_moves, nr, nc))

        # L
        nr, nc = r, c - 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            new_cost = cost + get_cost(nr, nc)
            new_moves = moves + "L"
            moves_to_try.append((new_cost, new_moves, nr, nc))

        # R
        nr, nc = r, c + 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            new_cost = cost + get_cost(nr, nc)
            new_moves = moves + "R"
            moves_to_try.append((new_cost, new_moves, nr, nc))

        # T (teleport) - only if current cell is a pad
        ch = grid[r][c]
        if ch.islower() and (r, c) in pad_map:
            tr, tc = pad_map[(r, c)]
            new_cost = cost + 2
            new_moves = moves + "T"
            moves_to_try.append((new_cost, new_moves, tr, tc))

        # U
        nr, nc = r - 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            new_cost = cost + get_cost(nr, nc)
            new_moves = moves + "U"
            moves_to_try.append((new_cost, new_moves, nr, nc))

        for item in moves_to_try:
            heapq.heappush(pq, item)

    return None
