            if cont_line[0] in (' ', '\t'):
                # Continuation line
                cont_value, next_j = _parse_value(cont_line, lines, j)
                sections[current_section][key_part] += '\n' + cont_value
                j = next_j
            else:
                break

        i = j if j > i else i + 1

    # Second pass: resolve interpolation
    result: dict[str, dict[str, str]] = {}

    def resolve(section: str, key: str, value: str, resolving: set) -> str:
        """Resolve ${...} references in value."""
        if (section, key) in resolving:
            raise ValueError(f"cycle detected in reference for {section}:{key}")

        result_str = []
        idx = 0
        while idx < len(value):
            if value[idx] == '$':
                if idx + 1 >= len(value):
                    result_str.append('$')
                    idx += 1
                elif value[idx + 1] == '$':
                    result_str.append('$')
                    idx += 2
                elif value[idx + 1] == '{':
                    # Find closing }
                    close_idx = value.find('}', idx + 2)
                    if close_idx == -1:
                        raise ValueError(f"unclosed reference in {section}:{key}")
                    ref = value[idx + 2:close_idx]

                    if ':' in ref:
                        ref_section, ref_key = ref.split(':', 1)
                        ref_key = ref_key.strip().lower()
                        ref_section = ref_section.strip()
                    else:
                        ref_section = section
                        ref_key = ref.strip().lower()

                    # Look up the referenced key
                    if ref_section not in sections or ref_key not in sections[ref_section]:
                        raise ValueError(f"undefined reference {ref} in {section}:{key}")

                    resolving.add((section, key))
                    resolved_value = resolve(ref_section, ref_key, sections[ref_section][ref_key], resolving)
                    resolving.discard((section, key))

                    result_str.append(resolved_value)
                    idx = close_idx + 1
                else:
                    result_str.append('$')
                    idx += 1
            else:
                result_str.append(value[idx])
                idx += 1

        return ''.join(result_str)

    for section, keys in sections.items():
        result[section] = {}
        for key, value in keys.items():
            resolved = resolve(section, key, value, set())
            result[section][key] = resolved

    # Remove empty default section if it has no keys
    if "" in result and len(result[""]) == 0:
        del result[""]

    return result


def _parse_value(value_part: str, lines: list[str], line_idx: int) -> tuple[str, int]:
    """Parse a value part, handling inline comments and quotes. Returns (value, next_line_index)."""
    value_part = value_part.strip()

    if value_part.startswith('"'):
        # Quoted value
        result = []
        idx = 1
        while idx < len(value_part):
            ch = value_part[idx]
            if ch == '\\' and idx + 1 < len(value_part) and value_part[idx + 1] == '"':
                result.append('"')
                idx += 2
            elif ch == '"':
                # Check for inline comment after closing quote
                rest = value_part[idx + 1:].strip()
                if rest == '' or rest.startswith('#') or rest.startswith(';'):
                    return ''.join(result), line_idx + 1
                else:
                    # This is an error - content after closing quote that's not a comment
                    raise ValueError(f"line {line_idx + 1}: unterminated quote")
            else:
                result.append(ch)
                idx += 1

        # If we get here, the quote was never closed
        raise ValueError(f"line {line_idx + 1}: unterminated quote")

    # Unquoted value - handle inline comments
    # Look for ; or # preceded by whitespace
    result = []
    idx = 0
    while idx < len(value_part):
        ch = value_part[idx]
        if (ch == ';' or ch == '#') and idx > 0 and value_part[idx - 1] in (' ', '\t'):
            # Inline comment
            break
        result.append(ch)
        idx += 1

    return ''.join(result).strip(), line_idx + 1
