    # Comparators are separated by whitespace
    tokens = s.split()

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token == '*':
            i += 1
            continue

        # Determine operator
        op = None
        rest = token

        if token.startswith('<='):
            op = '<='
            rest = token[2:]
        elif token.startswith('>='):
            op = '>='
            rest = token[2:]
        elif token.startswith('<'):
