        comps = _expand_comparator(op, m, mn, p, pre, build)
        comparators.extend(comps)

        i += 1

    return ComparatorSet(comparators)


def satisfies(version_str, rng):
    """Check if a version string satisfies a range string."""
    v = parse(version_str)

    # Parse the range into comparator sets
    sets = _parse_range(rng)

    for cs in sets:
        if cs.matches(v):
            return True

    return False


def _parse_range(rng):
    """Parse a full range string into a list of ComparatorSets."""
    rng = rng.strip()
    if not rng or rng == '*':
        return [ComparatorSet([])]

    # Split by ||
    parts = rng.split('||')
    sets = []
    for part in parts:
        part = part.strip()
        if not part or part == '*':
            sets.append(ComparatorSet([]))
        else:
            sets.append(_parse_comparator_set(part))

    return sets


def max_satisfying(versions, rng):
    """Return the original string of the maximum version that satisfies the range, or None."""
    if not versions:
        return None

    # Parse all versions and track which ones satisfy the range
    satisfying = []
    for v_str in versions:
        try:
            if satisfies(v_str, rng):
                satisfying.append((parse(v_str), v_str))
        except ValueError:
            continue

    if not satisfying:
        return None

    # Find the maximum by SemVer precedence
    max_v = max(satisfying, key=lambda x: x[0])
    return max_v[1]
