@total_ordering
class Version:
    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # list of identifiers or None
        self.build = build

    @property
    def has_prerelease(self):
        return self.prerelease is not None and len(self.prerelease) > 0

    def _compare_prerelease(self, other):
        """Compare prerelease of self vs other. Returns -1, 0, or 1."""
        self_has = self.has_prerelease
        other_has = other.has_prerelease

        if not self_has and not other_has:
            return 0
        if not self_has:
            # Release > prerelease
            return 1
        if not other_has:
            # Prerelease < release
            return -1

        self_ids = self.prerelease
        other_ids = other.prerelease

        for a, b in zip(self_ids, other_ids):
            if isinstance(a, int) and isinstance(b, int):
                if a != b:
                    return -1 if a < b else 1
            elif isinstance(a, int) and not isinstance(b, int):
                # Numeric < alphanumeric
                return -1
            elif not isinstance(a, int) and isinstance(b, int):
                # Alphanumeric > numeric
                return 1
            else:
                # Both strings, compare ASCII
                if a != b:
                    return -1 if a < b else 1

        # All compared identifiers are equal; shorter list is smaller
        if len(self_ids) < len(other_ids):
            return -1
        elif len(self_ids) > len(other_ids):
            return 1
        return 0

    def __eq__(self, other):
