                    i += 2
                else:
                    parts.append(('literal', next_ch))
                    has_content = True
                    i += 2

            elif ch == "'":
                i += 1
                start = i
                while i < n and line[i] != "'":
                    i += 1
                if i >= n:
                    raise ValueError("Unterminated single quote")
                content = line[start:i]
                parts.append(('quoted', content))
                has_content = True
                i += 1

            elif ch == '"':
                i += 1
                buf = []
                while i < n and line[i] != '"':
                    c = line[i]
                    if c == '\\' and i + 1 < n:
                        next_c = line[i+1]
                        if next_c in ('$', '"', '\\'):
                            buf.append(next_c)
                            i += 2
                        elif next_c == '\n':
                            i += 2
                        else:
                            buf.append('\\')
                            i += 1
                    elif c == '$':
                        expanded, new_i = parse_expansion_dq(i)
                        buf.append(expanded)
                        i = new_i
                    else:
                        buf.append(c)
                        i += 1
                if i >= n:
                    raise ValueError("Unterminated double quote")
                content = ''.join(buf)
                parts.append(('quoted', content))
                has_content = True
                i += 1

            elif ch == '$':
                expanded, new_i = parse_expansion_uq(i)
                parts.append(('unquoted_expansion', expanded))
                has_content = True
                i = new_i

            else:
                parts.append(('literal', ch))
                has_content = True
                i += 1

        return parts, has_content

    while i < n:
        skip_whitespace()
        if i >= n:
            break

        parts, has_content = parse_word()

        if not has_content:
            continue

        # Process parts to build final word(s) with field splitting for unquoted expansions
        result_words = []
        current_word_parts = []

        for part_type, content in parts:
            if part_type == 'unquoted_expansion':
                fields = content.split()
                if not fields:
                    # Empty expansion - don't add anything
                    pass
                else:
                    for f in fields:
                        if current_word_parts:
                            result_words.append(''.join(current_word_parts))
                            current_word_parts = []
                        result_words.append(f)
            else:
                current_word_parts.append(content)

        if current_word_parts:
            result_words.append(''.join(current_word_parts))

        words.extend(result_words)

    return words
