BEGIN {
    # Build a lookup table for character classification
    for (i = 48; i <= 57; i++) isword[sprintf("%c", i)] = 1   # digits
    for (i = 65; i <= 90; i++) isword[sprintf("%c", i)] = 1   # A-Z
    for (i = 97; i <= 122; i++) isword[sprintf("%c", i)] = 1  # a-z
    isword["\x27"] = 1  # apostrophe
}
{
    line = $0
    n = length(line)
    i = 1
    while (i <= n) {
        c = substr(line, i, 1)
        if ((c in isword)) {
            start = i
            while (i <= n) {
                c2 = substr(line, i, 1)
                if ((c2 in isword)) {
                    i++
                } else {
                    break
                }
            }
            token = substr(line, start, i - start)

            # Strip leading apostrophes
            while (length(token) > 0 && substr(token, 1, 1) == "\x27") {
                token = substr(token, 2)
            }
            # Strip trailing apostrophes
            while (length(token) > 0 && substr(token, length(token), 1) == "\x27") {
                token = substr(token, 1, length(token) - 1)
            }

            # If token is empty after stripping, skip it
            if (length(token) == 0) continue

            # If ignore case, convert to lowercase
            if (IGNORECASE + 0 == 1) {
                token = tolower(token)
            }

            count[token]++
        } else {
            i++
        }
    }
}
END {
    for (w in count) {
        print count[w], w
    }
